INSERT INTO artigos (slug,status,tipo,titulo,titulo_original,autor,autor_citacao,afiliacao,tradutor,periodico,volume,numero,ano,mes,paginas_original,editora_original,url_original,area,tema,tema_en,resumo,resumo_en,resumo_editorial,palavras_chave,direitos,pdf_url,pdf_paginas,capa_url,publicado_em) VALUES
('potgieter-imagens-deus-cantico-moises','publicado','traducao','Imagens de Deus, o Cântico de Moisés e metáforas','Images of God, the Song of Moses, and Metaphors','Annette Potgieter','POTGIETER, Annette','Stellenbosch University / Huguenot College','Gabriel Cantarino','Scriptura','122','1','2023',NULL,'1–13','Stellenbosch University','https://doi.org/10.7833/122-1-2087','Antigo Testamento','Cântico de Moisés · imagens de Deus','Song of Moses · images of God','Este artigo investigará as diversas maneiras pelas quais Deus é retratado no Cântico de Moisés. O Cântico de Moisés está situado no uso litúrgico das comunidades da Igreja Primitiva; consequentemente, o Cântico de Moisés constitui um caso particularmente adequado para examinar a linguagem empregada nas comunidades cristãs primitivas. O artigo utilizará a teoria da metáfora conceitual, rastreando os padrões metafóricos que surgem no texto a fim de delinear possíveis sistemas conceituais. Além disso, os significados desses modelos cognitivos encontrados no Cântico de Moisés, particularmente no que se refere à linguagem e às imagens divinas (bem como à sua utilização nas práticas eclesiais de modo mais geral), serão examinados neste ensaio.','This article will investigate the various ways in which God is portrayed in the Song of Moses. The Song of Moses is situated within the liturgical use of early church communities; accordingly, the Song of Moses serves as a particularly good test case for examining the language employed in early Christian communities. The article will use conceptual metaphor theory, tracing the metaphorical patterns that arise within the text to delineate possible conceptual systems. Moreover, the meanings of these cognitive models found in the Song of Moses, particularly as they relate to divine language and imagery (as well as their deployment in ecclesial practices more generally), will be deliberated upon in this essay.',0,'["Cântico de Moisés", "Deuteronômio 32", "metáforas", "imagens de Deus", "linguística cognitiva", "teoria da metáfora conceitual", "adoração", "liturgia"]','Publicado com autorização de Annette Potgieter (23/11/2026). Os direitos do texto original pertencem a Annette Potgieter e à Scriptura (Stellenbosch University), onde o artigo foi publicado sob licença CC BY-NC-ND. Tradução para o português © 2026 Gabriel Cantarino / The Prophetic Voices, para fins de estudo, sem fins lucrativos.','/artigos/potgieter-2023-imagens-deus-cantico-moises.pdf',15,'/artigos/potgieter-2023-imagens-deus-cantico-moises-capa.jpg','2026-11-23 16:05:00');
